import { readFileSync } from "node:fs";

const tokens = readFileSync(0, "utf8").trim().split(/\s+/).map(Number);

function transposeGrid(grid: number[][]): number[][] {
  const width = grid[0]?.length ?? 0;
  const result: number[][] = [];
  for (let c = 0; c < width; c++) {
    const column: number[] = [];
    for (const row of grid) {
      column.push(row[c] ?? 0);
    }
    result.push(column);
  }
  return result;
}

